import { Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshStandardNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // --- Textures --------------------------------------------------------------
  const colorTex = ctx.textureLoader.load(config.assets?.imageUrl ?? '');
  const depthTex = ctx.textureLoader.load(config.assets?.depthMapUrl ?? '');

  // --- Geometry ---------------------------------------------------------------
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // --- Material ---------------------------------------------------------------
  const material = new MeshStandardNodeMaterial({
    map: texture(colorTex),
    displacementMap: texture(depthTex),
    displacementScale: 0.12,
    metalness: 0.4,
    roughness: 0.6,
    clearcoat: 0.2,
    clearcoatRoughness: 0.1,
    color: 0xffffff,
  });

  // --- Mesh -------------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  mesh.name = config.name ?? 'pricing-list-row';

  // placement
  const pos = config.position ?? [0, 0, 0];
  const rot = config.rotation ?? [0, 0, 0];
  const scl = config.scale ?? [1, 1, 1];
  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // --- GSAP timeline for hover rise‑in ---------------------------------------
  const riseTimeline = gsap.timeline({ paused: true });
  riseTimeline.to(
    mesh.position,
    {
      y: mesh.position.y + 0.15,
      ease: 'power3.out',
      duration: 0.7,
    },
    0
  );

  // --- Event handlers ---------------------------------------------------------
  mesh.userData.handlers = {
    hover: (enter) => {
      if (enter) riseTimeline.play();
      else riseTimeline.reverse();
    },
    click: () => {
      if (typeof ctx.emit === 'function') {
        ctx.emit('hub-pricing.select');
      }
    },
  };

  // --- Apply cinematic primitives ---------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(mesh, prim.params);
      }
    });
  }

  // --- Cleanup ---------------------------------------------------------------
  mesh.userData.cleanup = () => {
    riseTimeline.kill();
    geometry.dispose();
    material.dispose();
    if (colorTex?.dispose) colorTex.dispose();
    if (depthTex?.dispose) depthTex.dispose();
    mesh.userData.handlers = null;
  };

  return mesh;
}
